-- Generated by Loom
-- Generator: satellite
-- Variant: standard
-- Hash function: sha256
{{ config(materialized='incremental', incremental_strategy='append') }}
WITH staged AS (
    SELECT
        LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR))))) AS customer_hk,
        LOWER(sha256(concat(COALESCE(CAST(s.customer_name AS VARCHAR), '~'), '|', COALESCE(CAST(s.customer_email AS VARCHAR), '~')))) AS __hash_diff,
        s.customer_name,
        s.customer_email,
        localtimestamp AS __loaded_at,
        'crm' AS __record_source
    FROM {{ ref('stg_customers') }} AS s
    JOIN {{ ref('hub_customer') }} AS p
        ON LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR))))) = p.customer_hk
)
{% if is_incremental() %}
, latest AS (
    SELECT customer_hk, __hash_diff
    FROM (
        SELECT
            customer_hk,
            __hash_diff,
            ROW_NUMBER() OVER (
                PARTITION BY customer_hk
                ORDER BY __loaded_at DESC, __hash_diff DESC
            ) AS rn
        FROM {{ this }}
    ) AS ranked
    WHERE rn = 1
)
{% endif %}
SELECT
    st.customer_hk,
    st.__hash_diff,
    st.customer_name,
    st.customer_email,
    st.__loaded_at,
    st.__record_source
FROM staged AS st
{% if is_incremental() %}
LEFT JOIN latest AS l
    ON st.customer_hk = l.customer_hk
WHERE l.customer_hk IS NULL
    OR st.__hash_diff <> l.__hash_diff
{% endif %}
